/* ПЕЧАТНЫЕ ФОРМЫ: счёт на оплату с QR-кодом (ГОСТ Р 56042-2014), акт об оказании услуг,
   товарная накладная ТОРГ-12, универсальный передаточный документ (статус 1 и 2).
   Таблицы: «книга-образец» — лист с реквизитами нашей организации и таблицей документов
   (строка — позиция, номер документа связывает строки); форма собирается на пустом листе,
   с настройкой печати. Документы: шаблоны для «Документы по шаблону» (слияние из таблицы
   в полной версии) — поля {{…}} совпадают с заголовками таблицы образца. */

const вДокументе = typeof документ !== 'undefined';
const МЕСЯЦЫ_Р = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
const ДЕНЬ = 86400000, ЭПОХА = Date.UTC(1899, 11, 30);
const вДату = n => new Date(ЭПОХА + Math.round(n) * ДЕНЬ);
const ДМГ = n => { if(typeof n !== 'number') return String(n || ''); const д = вДату(n); return String(д.getUTCDate()).padStart(2, '0') + '.' + String(д.getUTCMonth() + 1).padStart(2, '0') + '.' + д.getUTCFullYear(); };
const датаСловом = n => { if(typeof n !== 'number') return String(n || ''); const д = вДату(n); return д.getUTCDate() + ' ' + МЕСЯЦЫ_Р[д.getUTCMonth()] + ' ' + д.getUTCFullYear() + ' г.'; };
const деньги = x => (Math.round(x * 100) / 100).toLocaleString('ru-RU', {minimumFractionDigits: 2, maximumFractionDigits: 2}).replace(/ /g, ' ');

/* ===== сумма прописью ===== */
const ЕД = [['', 'один', 'два', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять'], ['', 'одна', 'две', 'три', 'четыре', 'пять', 'шесть', 'семь', 'восемь', 'девять']];
const ДЕСЯТЬ = ['десять', 'одиннадцать', 'двенадцать', 'тринадцать', 'четырнадцать', 'пятнадцать', 'шестнадцать', 'семнадцать', 'восемнадцать', 'девятнадцать'];
const ДЕСЯТКИ = ['', '', 'двадцать', 'тридцать', 'сорок', 'пятьдесят', 'шестьдесят', 'семьдесят', 'восемьдесят', 'девяносто'];
const СОТНИ = ['', 'сто', 'двести', 'триста', 'четыреста', 'пятьсот', 'шестьсот', 'семьсот', 'восемьсот', 'девятьсот'];
const форма = (n, ф) => { const a = n % 100, b = n % 10; return a > 10 && a < 20 ? ф[2] : b === 1 ? ф[0] : b >= 2 && b <= 4 ? ф[1] : ф[2]; };
function тройка(n, жен){ const с = Math.floor(n / 100), д = Math.floor(n % 100 / 10), е = n % 10, out = [];
  if(с) out.push(СОТНИ[с]); if(д === 1) out.push(ДЕСЯТЬ[е]); else { if(д) out.push(ДЕСЯТКИ[д]); if(е) out.push(ЕД[жен ? 1 : 0][е]); } return out.join(' '); }
function числоПрописью(n, жен = false){
  if(n === 0) return 'ноль';
  const ступени = [[null, жен], [['тысяча', 'тысячи', 'тысяч'], true], [['миллион', 'миллиона', 'миллионов'], false], [['миллиард', 'миллиарда', 'миллиардов'], false]];
  const части = [];
  for(let i = 0; n > 0 && i < ступени.length; i++, n = Math.floor(n / 1000)){
    const т = n % 1000; if(!т) continue;
    const [ф, ж] = ступени[i];
    части.unshift(тройка(т, ж) + (ф ? ' ' + форма(т, ф) : ''));
  }
  return части.join(' ');
}
function прописью(сумма){
  const к = Math.round(Math.abs(сумма) * 100), р = Math.floor(к / 100), коп = к % 100;
  const т = числоПрописью(р) + ' ' + форма(р, ['рубль', 'рубля', 'рублей']) + ' ' + String(коп).padStart(2, '0') + ' ' + форма(коп, ['копейка', 'копейки', 'копеек']);
  return т.charAt(0).toUpperCase() + т.slice(1);
}

/* ===== Документы: шаблоны для слияния ===== */
const ШАБЛОНЫ_ДОК = [
  {имя: 'Счёт на оплату — для «По шаблону»', блоки: [
    '<p><b>[Наша организация]</b>, ИНН [ИНН], КПП [КПП]<br>[Адрес], тел. [Телефон]</p>',
    '<table><tr><td>Банк получателя: [Банк]</td><td>БИК</td><td>[БИК]</td></tr><tr><td>ИНН [ИНН], КПП [КПП]<br>Получатель: [Наша организация]</td><td>Сч. №</td><td>[Расчётный счёт]<br>к/с [Корр. счёт]</td></tr></table>',
    '<h1>Счёт на оплату № {{#ключ Номер}} от {{Дата|дд.мм.гггг}}</h1>',
    '<p>Покупатель: {{Покупатель}}, ИНН {{ИНН покупателя}}, КПП {{КПП покупателя}}, {{Адрес покупателя}}<br>Основание: {{Основание}}</p>',
    '<table><tr><th>№</th><th>Товары (работы, услуги)</th><th>Кол-во</th><th>Ед.</th><th>Цена</th><th>Сумма</th></tr><tr data-строки><td>{{#н}}</td><td>{{Наименование}}</td><td>{{Кол-во}}</td><td>{{Ед.}}</td><td>{{Цена|#,##0.00}}</td><td>{{Всего|#,##0.00}}</td></tr></table>',
    '<p style="text-align:right">Итого: {{#итог Всего|#,##0.00}}<br>В том числе НДС: {{#итог НДС|#,##0.00}}</p>',
    '<p>Всего наименований {{#кол}}, на сумму {{#итог Всего|#,##0.00}} руб.<br><b>{{#итог Всего|прописью}}</b></p>',
    '<p>&nbsp;</p>', '<p>Руководитель ____________ [И. О. Фамилия]      Бухгалтер ____________ [И. О. Фамилия]</p>']},
  {имя: 'Акт об оказании услуг — для «По шаблону»', блоки: [
    '<h1>Акт № {{#ключ Номер}} от {{Дата|дд.мм.гггг}}</h1>',
    '<p>Исполнитель: <b>[Наша организация]</b>, ИНН [ИНН], КПП [КПП], [Адрес]<br>Заказчик: <b>{{Покупатель}}</b>, ИНН {{ИНН покупателя}}, КПП {{КПП покупателя}}, {{Адрес покупателя}}<br>Основание: {{Основание}}</p>',
    '<table><tr><th>№</th><th>Наименование работ, услуг</th><th>Кол-во</th><th>Ед.</th><th>Цена</th><th>Сумма</th></tr><tr data-строки><td>{{#н}}</td><td>{{Наименование}}</td><td>{{Кол-во}}</td><td>{{Ед.}}</td><td>{{Цена|#,##0.00}}</td><td>{{Всего|#,##0.00}}</td></tr></table>',
    '<p style="text-align:right">Итого: {{#итог Всего|#,##0.00}}<br>В том числе НДС: {{#итог НДС|#,##0.00}}</p>',
    '<p>Всего оказано услуг {{#кол}}, на сумму {{#итог Всего|#,##0.00}} руб.<br><b>{{#итог Всего|прописью}}</b></p>',
    '<p>Вышеперечисленные услуги выполнены полностью и в срок. Заказчик претензий по объёму, качеству и срокам оказания услуг не имеет.</p>',
    '<p>&nbsp;</p>', '<table><tr><td style="border:none;width:50%">Исполнитель<br><br>____________ [И. О. Фамилия]</td><td style="border:none">Заказчик<br><br>____________ </td></tr></table>']},
];
async function вставитьШаблонДок(ш){
  const блоки = документ.блоки;
  const пуст = блоки.every(б => !String(б.текст || '').trim() && !/<table/i.test(б.html || ''));
  if(!пуст && !(await диалог.вопрос('Шаблон для слияния лучше вставлять в пустой документ. Вставить в конец этого?'))) return;
  const где = пуст ? 0 : блоки.length, было = блоки.length;
  ш.блоки.forEach((h, k) => документ.вставить(где + k, h.replace(/\[([^\[\]<>]{1,80})\]/g, '<span style="background:#fff3b0">[$1]</span>')));
  if(пуст) for(let i = было - 1; i >= 0; i--) документ.удалить(ш.блоки.length + i);
  документ.перейти(0);
  панель.сообщение('Шаблон вставлен. Заполните [подсвеченные] реквизиты, сохраните документ как .plsd — и в Таблицах: выделите таблицу «Документы» → Команда → «По шаблону…» (полная версия).');
}

/* ===== Таблицы ===== */
/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}
/* ===== QR-код (ISO/IEC 18004): байтовый режим, UTF-8, уровень коррекции M, версии 1–40 ===== */
const QR = (() => {
  const ECC_M = [-1, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28];
  const БЛОКИ_M = [-1, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49];
  const модулей = v => { let r = (16 * v + 128) * v + 64; if(v >= 2){ const n = Math.floor(v / 7) + 2; r -= (25 * n - 10) * n - 55; if(v >= 7) r -= 36; } return r; };
  const данных = v => Math.floor(модулей(v) / 8) - ECC_M[v] * БЛОКИ_M[v];
  const умн = (x, y) => { let z = 0; for(let i = 7; i >= 0; i--){ z = (z << 1) ^ ((z >>> 7) * 0x11D); z ^= ((y >>> i) & 1) * x; } return z; };
  function делитель(n){
    const р = new Array(n).fill(0); р[n - 1] = 1; let корень = 1;
    for(let i = 0; i < n; i++){ for(let j = 0; j < n; j++){ р[j] = умн(р[j], корень); if(j + 1 < n) р[j] ^= р[j + 1]; } корень = умн(корень, 2); }
    return р;
  }
  function остаток(данные, д){
    const р = new Array(д.length).fill(0);
    for(const b of данные){ const f = b ^ р.shift(); р.push(0); д.forEach((k, i) => { р[i] ^= умн(k, f); }); }
    return р;
  }
  function utf8(т){ const out = []; for(const ch of String(т)){ let c = ch.codePointAt(0);
    if(c < 0x80) out.push(c); else if(c < 0x800) out.push(0xC0 | c >> 6, 0x80 | c & 63);
    else if(c < 0x10000) out.push(0xE0 | c >> 12, 0x80 | c >> 6 & 63, 0x80 | c & 63);
    else out.push(0xF0 | c >> 18, 0x80 | c >> 12 & 63, 0x80 | c >> 6 & 63, 0x80 | c & 63); } return out; }
  function выравнивание(v){
    if(v === 1) return [];
    const n = Math.floor(v / 7) + 2, шаг = v === 32 ? 26 : Math.ceil((v * 4 + 4) / (n * 2 - 2)) * 2, р = [6];
    for(let pos = v * 4 + 10; р.length < n; pos -= шаг) р.splice(1, 0, pos);
    return р;
  }
  function сделать(текст){
    const байты = utf8(текст);
    let v = 1;
    for(; v <= 40; v++){ const бит = 4 + (v < 10 ? 8 : 16) + 8 * байты.length; if(бит <= данных(v) * 8) break; }
    if(v > 40) throw new Error('Слишком длинный текст для QR-кода');
    /* поток битов */
    const биты = [];
    const доб = (x, n) => { for(let i = n - 1; i >= 0; i--) биты.push((x >>> i) & 1); };
    доб(4, 4); доб(байты.length, v < 10 ? 8 : 16); байты.forEach(b => доб(b, 8));
    const ёмк = данных(v) * 8;
    доб(0, Math.min(4, ёмк - биты.length));
    доб(0, (8 - биты.length % 8) % 8);
    for(let p = 0xEC; биты.length < ёмк; p ^= 0xEC ^ 0x11) доб(p, 8);
    const слова = []; for(let i = 0; i < биты.length; i += 8){ let b = 0; for(let j = 0; j < 8; j++) b = b << 1 | биты[i + j]; слова.push(b); }
    /* блоки и коррекция, чередование */
    const nБ = БЛОКИ_M[v], eБ = ECC_M[v], всего = Math.floor(модулей(v) / 8), коротких = nБ - всего % nБ, длКор = Math.floor(всего / nБ), д = делитель(eБ);
    const блоки = []; let k = 0;
    for(let i = 0; i < nБ; i++){
      const dat = слова.slice(k, k + длКор - eБ + (i < коротких ? 0 : 1)); k += dat.length;
      const ecc = остаток(dat, д); if(i < коротких) dat.push(0);
      блоки.push(dat.concat(ecc));
    }
    const поток = [];
    for(let i = 0; i < блоки[0].length; i++) блоки.forEach((б, j) => { if(i !== длКор - eБ || j >= коротких) поток.push(б[i]); });
    /* поле */
    const N = v * 4 + 17, м = Array.from({length: N}, () => new Array(N).fill(false)), служ = Array.from({length: N}, () => new Array(N).fill(false));
    const ставь = (x, y, тёмн) => { м[y][x] = тёмн; служ[y][x] = true; };
    for(let i = 0; i < N; i++){ ставь(6, i, i % 2 === 0); ставь(i, 6, i % 2 === 0); }
    const искатель = (x, y) => { for(let dy = -4; dy <= 4; dy++) for(let dx = -4; dx <= 4; dx++){ const d = Math.max(Math.abs(dx), Math.abs(dy)), xx = x + dx, yy = y + dy; if(xx >= 0 && xx < N && yy >= 0 && yy < N) ставь(xx, yy, d !== 2 && d !== 4); } };
    искатель(3, 3); искатель(N - 4, 3); искатель(3, N - 4);
    const ал = выравнивание(v), na = ал.length;
    for(let i = 0; i < na; i++) for(let j = 0; j < na; j++){
      if((i === 0 && j === 0) || (i === 0 && j === na - 1) || (i === na - 1 && j === 0)) continue;
      for(let dy = -2; dy <= 2; dy++) for(let dx = -2; dx <= 2; dx++) ставь(ал[i] + dx, ал[j] + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1);
    }
    const формат = маска => {
      const data = 0 << 3 | маска; let r = data;                 /* уровень M: биты 00 */
      for(let i = 0; i < 10; i++) r = (r << 1) ^ ((r >>> 9) * 0x537);
      const b = (data << 10 | r) ^ 0x5412, бит = i => ((b >>> i) & 1) === 1;
      for(let i = 0; i <= 5; i++) ставь(8, i, бит(i));
      ставь(8, 7, бит(6)); ставь(8, 8, бит(7)); ставь(7, 8, бит(8));
      for(let i = 9; i < 15; i++) ставь(14 - i, 8, бит(i));
