/* ===== Счёт на оплату ===== */
function строкаQR(о, док){
  const чисто = т => String(т).replace(/\|/g, '/').replace(/\s+/g, ' ').trim();
  const назн = 'Оплата по счёту № ' + док.номер + ' от ' + ДМГ(док.дата) + '. ' + (док.безНДС ? 'НДС не облагается' : 'В т. ч. НДС ' + деньги(док.ндс) + ' руб.');
  return 'ST00012|Name=' + чисто(о.имя) + '|PersonalAcc=' + чисто(о.рс) + '|BankName=' + чисто(о.банк) + '|BIC=' + чисто(о.бик) + '|CorrespAcc=' + чисто(о.кс)
    + '|PayeeINN=' + чисто(о.инн) + (о.кпп ? '|KPP=' + чисто(о.кпп) : '') + '|Purpose=' + чисто(назн).slice(0, 210) + '|Sum=' + Math.round(док.всего * 100);
}
