/* общий вид шапки таблицы из двух строк: одиночные графы — текст в нижней строке, рамка без черты между строками;
   группы — подпись в верхней строке (объединение только между одиночными соседями) */
function шапкаТаблицы(r1, графы, шрифт = 7){
  const r2 = r1 + 1, Ш = {b: 1, size: шрифт, align: 'center', valign: 'middle', wrap: 1};
  const л = {вид: 'тонкая', цвет: '#000000'};
  графы.forEach(г => {
    if(г.группа){
      const [c1, c2] = г.с;
      if(г.слить){ слить(r1, c1, r1, c2); пиши(r1, c1, г.группа, Ш); }
      else пиши(r1, c1, г.группа, Object.assign({}, Ш, {align: 'left', wrap: 0}));
      for(let c = c1; c <= c2; c++){ const гр = {в: л, н: л}; if(c === c1) гр.л = л; if(c === c2) гр.п = л; клетка(r1, c).стиль = {гр}; }
      г.под.forEach((т, k) => пиши(r2, c1 + k, т, Object.assign({}, Ш, {гр: ЧЁРН})));
    } else {
      пиши(r2, г.с, г.т, Object.assign({}, Ш, {гр: {н: л, л, п: л}}));
      клетка(r1, г.с).стиль = {гр: {в: л, л, п: л}};
    }
  });
}
/* верхняя граница групп, объединённых в шапке, — чертой у строки выше */
