  высотаСтроки(r1, 50); высотаСтроки(r1 + 1, 124);
  ['А', '1', '1а', '1б', '2', '2а', '3', '4', '5', '6', '7', '8', '9', '10', '10а', '11', '12', '12а', '13'].forEach((т, j) => пиши(r1 + 2, j, т, {size: 7, align: 'center', гр: ЧЁРН}));
