    в.forEach((v, j) => пиши(r, j, v, Object.assign({}, Я, j === 2 ? {wrap: 1} : j === 6 ? КОЛ : [7, 8, 11, 12].includes(j) ? ДЕН : j === 9 ? {align: 'center', size: 7} : {align: 'center'})));
