const ФОРМЫ = ['Счёт на оплату с QR-кодом', 'Счёт на оплату', 'Акт об оказании услуг', 'Товарная накладная ТОРГ-12', 'УПД, статус 1 (счёт-фактура и передаточный документ)', 'УПД, статус 2 (передаточный документ)'];
async function Сформировать(){
  if(вДокументе){ панель.сообщение('Формы собираются в Пульс Таблицах; здесь — шаблоны для слияния (вкладка «Для слияния»).'); return; }
  const п = параметры({});
  const д = await данные();
  if(!д){ панель.сообщение('Не нашёл лист с данными: в клетке A1 должно быть «Наша организация». Нажмите «Книга-образец» на пустом листе.'); return; }
  const лСейчас = книга.выделение ? книга.выделение.лист : книга.листы[0];
  if(лСейчас === д.лист){ панель.сообщение('Это лист с данными. Добавьте пустой лист (кнопка «+» внизу), откройте панель снова и нажмите «Сформировать» там.'); return; }
  const номер = String(п.номер || '').split(' — ')[0].trim();
  const док = документПо(д, номер);
  if(!док){ панель.сообщение('Выберите документ в списке (кнопка «Обновить список», если его там нет).'); return; }
  if(!(await областьПуста(0, 0, 60, 20)) && !(await диалог.вопрос('Лист не пуст. Сформировать форму поверх? Лучше — на пустом листе.'))) return;
  const форма = п.форма || ФОРМЫ[0];
  if(/QR/.test(форма) && (!/^\d{20}$/.test(String(д.орг['Расчётный счёт'] || '').replace(/\s/g, '')) || !/^\d{9}$/.test(String(д.орг['БИК'] || '').trim()))) сообщить('Внимание: расчётный счёт должен быть из 20 цифр, БИК — из 9, иначе банк не примет QR-код.');
  if(/^Счёт/.test(форма)) await счёт(д, док, /QR/.test(форма));
  else if(/^Акт/.test(форма)) акт(д, док);
  else if(/ТОРГ/.test(форма)) торг12(д, док);
  else упд(д, док, /статус 2/.test(форма) ? 2 : 1);
  await обновитьВысоты();
  панель.сообщение('Готово: ' + форма.replace(/ \(.*\)$/, '') + ' № ' + док.номер + ' — ' + деньги(док.всего) + ' ₽. Печать настроена: A4, ' + (/ТОРГ|УПД/.test(форма) ? 'альбомная' : 'книжная') + ', по ширине страницы.');
}
